package com.hospital.service;
import com.hospital.dao.*;import com.hospital.model.*;import com.hospital.util.*;import java.sql.*;import java.time.LocalDate;import java.util.*;
public class PatientService {
 private final PatientDAO dao=new PatientDAO();private final AuditDAO audit=new AuditDAO();
 public long register(User u,String name,String dob,String gender,String phone,String address,String blood)throws SQLException{Access.require(u,Role.ADMIN,Role.RECEPTIONIST);long id=dao.create(InputValidator.required(name,"Name"),java.sql.Date.valueOf(InputValidator.birthDate(dob)),InputValidator.required(gender,"Gender"),InputValidator.phone(phone),InputValidator.required(address,"Address"),blood==null||blood.isBlank()?null:blood);audit.record(u.id(),"PATIENT_REGISTERED","PATIENT",id,"Patient registered");return id;}
 public List<Patient> search(User u,String term,int page)throws SQLException{Access.require(u,Role.ADMIN,Role.RECEPTIONIST,Role.DOCTOR);if(page<1)throw new IllegalArgumentException("Page must be at least 1.");if(u.role()==Role.DOCTOR&&u.doctorId()==null)throw new SecurityException("Doctor account is not assigned to a doctor profile.");return dao.search(term,25,(page-1)*25,u.role()==Role.DOCTOR?u.doctorId():null);}
 public Patient get(User u,long id)throws SQLException{Access.require(u,Role.ADMIN,Role.RECEPTIONIST,Role.DOCTOR);if(u.role()==Role.DOCTOR&&u.doctorId()==null)throw new SecurityException("Doctor account is not assigned to a doctor profile.");Patient p=dao.find(id,u.role()==Role.DOCTOR?u.doctorId():null);if(p==null)throw new IllegalArgumentException("Patient not found.");return p;}
 public void update(User u,long id,String name,String dob,String gender,String phone,String address,String blood)throws SQLException{Access.require(u,Role.ADMIN,Role.RECEPTIONIST);dao.update(id,name,java.sql.Date.valueOf(InputValidator.birthDate(dob)),gender,InputValidator.phone(phone),address,blood);audit.record(u.id(),"PATIENT_UPDATED","PATIENT",id,"Patient demographic information updated");}
 public void deactivate(User u,long id)throws SQLException{Access.require(u,Role.ADMIN,Role.RECEPTIONIST);dao.deactivate(id);audit.record(u.id(),"PATIENT_DEACTIVATED","PATIENT",id,"Patient deactivated");}
}
